insert into public.specialist_reviews (specialist_id, author, city, child_age, rating, lang, body, created_on)
values
  ('p1', 'Жибек', 'almaty', '10-13', 5, 'ru', 'Были на первой консультации. Дочка стала чётче выговаривать звуки. Ребёнок с удовольствием идёт на занятия. Рекомендую!', '2026-02-28'),
  ('p1', 'Мария', 'almaty', '10-13', 4, 'ru', 'Долго искали своего специалиста. Ребёнок с удовольствием идёт на занятия. Будем продолжать.', '2026-10-25'),
  ('p2', 'Анель', 'astana', '0-2', 5, 'ru', 'Ходим уже 3 месяца. Сын начал говорить первые слова. Ребёнок с удовольствием идёт на занятия. Спасибо за терпение.', '2026-03-09'),
  ('p2', 'Елена', 'astana', '6-9', 4, 'kk', 'Аналар чатындағы ұсыныс бойынша таптық. Қызым дыбыстарды анығырақ айтатын болды. Өте ризамыз.', '2026-08-20'),
  ('p3', 'Томирис', 'almaty', '3-5', 5, 'kk', '3 ай болды қатынап жүрміз. Үйге түсінікті жаттығулар берді. Жалғастырамыз.', '2026-07-11'),
  ('p3', 'Әсел', 'almaty', '3-5', 5, 'ru', 'Занимаемся с весны. Ребёнок с удовольствием идёт на занятия. Дала понятные упражнения на дом. Спасибо за терпение.', '2026-07-14'),
  ('p3', 'Сабина', 'almaty', '3-5', 3, 'kk', '3 ай болды қатынап жүрміз. Ұлым алғашқы сөздерін айта бастады. Үйге түсінікті жаттығулар берді. Сабақтан кейін көбірек кері байланыс болса екен.', '2026-06-01'),
  ('p3', 'Томирис', 'almaty', '3-5', 4, 'ru', 'Были на первой консультации. Дала понятные упражнения на дом. Очень довольны.', '2026-09-10'),
  ('p5', 'Айгуль', 'almaty', '10-13', 5, 'ru', 'Ходим уже 2 месяца. Домашние задания теперь без слёз. Ребёнку стало легче сосредоточиться на уроках. Очень довольны.', '2026-09-19'),
  ('p5', 'Юлия', 'almaty', '3-5', 5, 'ru', 'Занимаемся с весны. Подобрала упражнения на внимание и память. Рекомендую!', '2025-12-21'),
  ('p5', 'Татьяна', 'almaty', '3-5', 5, 'ru', 'Были на первой консультации. Ребёнку стало легче сосредоточиться на уроках. Подобрала упражнения на внимание и память. Очень довольны.', '2026-05-14'),
  ('p5', 'Мария', 'almaty', '6-9', 3, 'kk', 'Өз маманымызды ұзақ іздедік. Қысымсыз, сабырмен түсіндіреді. Әзірге нәтиже аз, әрі қарай көреміз.', '2026-01-28'),
  ('p6', 'Ольга', 'kostanay', '3-5', 5, 'kk', 'Өз маманымызды ұзақ іздедік. Зейін мен есте сақтауға жаттығулар таңдады. Қысымсыз, сабырмен түсіндіреді. Жалғастырамыз.', '2026-01-05'),
  ('p7', 'Айжан', 'almaty', '3-5', 4, 'kk', 'Өз маманымызды ұзақ іздедік. Ұлым алғашқы сөздерін айта бастады. Ұсынамын!', '2026-06-16'),
  ('p7', 'Алия', 'almaty', '14-17', 5, 'ru', 'Ходим уже 2 месяца. Дала понятные упражнения на дом. Очень довольны.', '2026-07-20'),
  ('p7', 'Гульнара', 'almaty', '3-5', 5, 'ru', 'Долго искали своего специалиста. Ребёнок с удовольствием идёт на занятия. Дочка стала чётче выговаривать звуки. Будем продолжать.', '2026-05-16'),
  ('p8', 'Татьяна', 'almaty', '6-9', 5, 'kk', 'Алғашқы кеңесте болдық. Үйге түсінікті жаттығулар берді. Қызым дыбыстарды анығырақ айтатын болды. Өте ризамыз.', '2026-02-12'),
  ('p8', 'Зарина', 'almaty', '6-9', 5, 'ru', 'Ходим уже 2 месяца. Дочка стала чётче выговаривать звуки. Рекомендую!', '2026-04-13'),
  ('p8', 'Наталья', 'almaty', '3-5', 5, 'kk', 'Өз маманымызды ұзақ іздедік. Қызым дыбыстарды анығырақ айтатын болды. Жалғастырамыз.', '2026-07-20'),
  ('p8', 'Гульнара', 'almaty', '6-9', 5, 'ru', 'Ходим уже 4 месяца. Дочка стала чётче выговаривать звуки. Дала понятные упражнения на дом. Очень довольны.', '2026-04-20'),
  ('p8', 'Әсел', 'almaty', '6-9', 3, 'ru', 'Занимаемся с весны. Дочка стала чётче выговаривать звуки. Дала понятные упражнения на дом. Пока результат небольшой, посмотрим дальше.', '2026-11-11'),
  ('p8', 'Салтанат', 'almaty', '3-5', 5, 'ru', 'Занимаемся с весны. Дочка стала чётче выговаривать звуки. Дала понятные упражнения на дом. Спасибо за терпение.', '2026-08-08'),
  ('p8', 'Карина', 'almaty', '6-9', 5, 'ru', 'Были на первой консультации. Дала понятные упражнения на дом. Ребёнок с удовольствием идёт на занятия. Рекомендую!', '2026-04-22'),
  ('p9', 'Гаухар', 'almaty', '6-9', 5, 'ru', 'Нашли по рекомендации в чате мам. Дала понятные упражнения на дом. Ребёнок с удовольствием идёт на занятия. Очень довольны.', '2026-05-15'),
  ('p9', 'Анель', 'almaty', '10-13', 5, 'kk', 'Көктемнен бері айналысып жүрміз. Қызым дыбыстарды анығырақ айтатын болды. Шыдамдылығыңызға рақмет.', '2026-10-03'),
  ('p9', 'Мария', 'almaty', '10-13', 5, 'ru', 'Занимаемся с весны. Ребёнок с удовольствием идёт на занятия. Дочка стала чётче выговаривать звуки. Очень довольны.', '2026-03-07'),
